25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export type StepResult =
41	  | { premium: number }
42	  | { payout: number; remainingCap: number };
43	
44	export interface ScenarioResult {
45	  results: StepResult[];
46	}
47	
48	const PROCESSING_FEE = 5;
49	const FIRST_INSURANCE_SURCHARGE = 0.1;
50	
51	const BASE_PREMIUMS = {
52	  sword: 100,
53	  amulet: 60,
54	  staff: 80,
55	  potion: 40,
56	  rune: 25,
57	  moonstone: 25,
58	} as const satisfies Record<string, number>;
59	
60	type InsurableItemType = keyof typeof BASE_PREMIUMS;
61	
62	const basePremiumOf = (item: Item): number =>
63	  BASE_PREMIUMS[item.type as InsurableItemType];
64	
65	/** Premiums are rounded up — in MHPCO's favour. */
66	const roundPremium = (amount: number): number => Math.ceil(amount);
67	
68	const COMPONENT_BLOCK_SIZE = 3;
69	const COMPONENT_BLOCK_PREMIUM = 60;
70	
71	const groupByType = (items: Item[]): Item[][] => {
72	  const groups = new Map<string, Item[]>();
73	  for (const item of items) {
74	    const group = groups.get(item.type) ?? [];
75	    group.push(item);
76	    groups.set(item.type, group);
77	  }
78	  return [...groups.values()];
79	};
80	
81	const groupBasePremium = (group: Item[]): number =>
82	  group.length === COMPONENT_BLOCK_SIZE
83	    ? COMPONENT_BLOCK_PREMIUM
84	    : group.reduce((sum, item) => sum + basePremiumOf(item), 0);
85	
86	const policyBasePremiumFor = (items: Item[]): number =>
87	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
88	
89	const quotePremium = (items: Item[]): number => {
90	  const policyBasePremium = policyBasePremiumFor(items);
91	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE;
92	  return roundPremium(
93	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
94	  );
95	};
96	
97	const runStep = (step: Step): StepResult => {
98	  if (step.op === "quote") {
99	    return { premium: quotePremium(step.items) };
100	  }
101	  throw new Error(`Unsupported step: ${step.op}`);
102	};
103	
104	export const runScenario = (scenario: Scenario): ScenarioResult => ({
105	  results: scenario.steps.map(runStep),
106	});
